import { chromium } from 'playwright';
import assert from 'node:assert/strict';
const browser = await chromium.launch({headless: true, args: ['--no-sandbox']});
const page = await browser.newPage({viewport: {width: 1440, height: 1080}});
const errors = [];
page.on('pageerror', error => errors.push(error.message));
await page.goto('http://localhost:5176');
await page.getByRole('heading', {name: 'Хорошие новости. Без лишнего шума.'}).waitFor();
await page.screenshot({path: '/tmp/ping-desktop.png', fullPage: true});
await page.clock.install();
const show = page.getByRole('button', {name: 'Показать уведомление'});
const toast = page.locator('.live-toast');
assert.equal(await toast.count(), 0);
await show.click();
assert.equal(await toast.count(), 1);
assert.match(await toast.innerText(), /Всё получилось/);
await page.clock.runFor(4900);
assert.equal(await toast.count(), 1);
await page.clock.runFor(400);
assert.equal(await toast.count(), 0);
await page.getByRole('button', {name: '3 сек', exact: true}).click();
await show.click();
await page.clock.runFor(2000);
await show.click();
await page.clock.runFor(1500);
assert.equal(await toast.count(), 1, 'Click resets the auto-dismiss timer');
await page.clock.runFor(1800);
assert.equal(await toast.count(), 0);
await show.click();
await page.getByRole('button', {name: 'Закрыть уведомление'}).click();
await page.clock.runFor(250);
assert.equal(await toast.count(), 0);
await show.click();
await page.keyboard.press('Escape');
await page.clock.runFor(250);
assert.equal(await toast.count(), 0);
await page.getByRole('combobox').click();
await page.getByRole('option', {name: 'Ошибка', exact:true}).click();
await show.click();
assert.match(await toast.innerText(), /Что-то пошло не так/);
await page.screenshot({path: '/tmp/ping-toast.png', fullPage: true});
await page.setViewportSize({width: 390, height: 844});
await page.screenshot({path: '/tmp/ping-mobile.png', fullPage: true});
assert.equal(await page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth), true, 'No horizontal overflow on mobile');
const bounds = await show.boundingBox();
assert.ok(bounds.x >= 0 && bounds.x + bounds.width <= 390);
assert.deepEqual(errors, []);
console.log('PASS: display, default 5-second auto-dismiss, timer reset, manual close, Escape, type selection, mobile layout, no browser errors.');
await browser.close();
EOF"

